arguments.command:
printf '#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
esac
' > /tmp/git-askpass.sh && chmod 700 /tmp/git-askpass.sh && cat /tmp/git-askpass.sh && test -n "$GITHUB_TOKEN" && echo "token present (length ${#GITHUB_TOKEN})"

content.text:
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
esac
token present (length 377)
